import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

export default function AdminHomeManager() {
  const [data, setData] = useState({
    heroTitle: "",
    heroSubtitle: "",
    aboutHeading: "",
    aboutText: "",
    missionText: "",
    visionText: "",
  });
  const [loading, setLoading] = useState(true);

  // ✅ Fetch existing home content
  useEffect(() => {
    axios
      .get("http://localhost:5000/api/home")
      .then((res) => {
        setData(res.data || {});
        setLoading(false);
      })
      .catch((err) => {
        console.error(err);
        toast.error("Failed to fetch home data");
        setLoading(false);
      });
  }, []);

  // ✅ Handle Input Change
  const handleChange = (e) => {
    setData({ ...data, [e.target.name]: e.target.value });
  };

  // ✅ Update Home Data
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.put("http://localhost:5000/api/home", data);
      toast.success("Home page updated successfully!");
    } catch (err) {
      console.error(err);
      toast.error("Failed to update content!");
    }
  };

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div className="admin-container">
      <Toaster position="top-right" />

      <h2 className="admin-title">🏠 Manage Home Page</h2>
      <p className="admin-subtitle">
        Update the text and section content shown on your school’s main homepage.
      </p>

      <form className="admin-form" onSubmit={handleSubmit}>
        <div className="admin-card">
          <h3 className="admin-section-title">Hero Section</h3>
          <label>Hero Title</label>
          <input
            type="text"
            name="heroTitle"
            value={data.heroTitle || ""}
            onChange={handleChange}
            placeholder="Enter hero title (e.g. 'Welcome to KV School')"
          />

          <label>Hero Subtitle</label>
          <textarea
            name="heroSubtitle"
            value={data.heroSubtitle || ""}
            onChange={handleChange}
            placeholder="Enter a short subtitle or tagline"
          />
        </div>

        <div className="admin-card">
          <h3 className="admin-section-title">About Section</h3>
          <label>About Heading</label>
          <input
            type="text"
            name="aboutHeading"
            value={data.aboutHeading || ""}
            onChange={handleChange}
            placeholder="Enter About section title"
          />

          <label>About Text</label>
          <textarea
            name="aboutText"
            value={data.aboutText || ""}
            onChange={handleChange}
            placeholder="Write a brief about your school"
          />
        </div>

        <div className="admin-card">
          <h3 className="admin-section-title">Mission & Vision</h3>

          <label>Mission</label>
          <textarea
            name="missionText"
            value={data.missionText || ""}
            onChange={handleChange}
            placeholder="Describe your school's mission"
          />

          <label>Vision</label>
          <textarea
            name="visionText"
            value={data.visionText || ""}
            onChange={handleChange}
            placeholder="Describe your school's vision"
          />
        </div>

        <button type="submit" className="admin-save-btn">
          💾 Save Changes
        </button>
      </form>
    </div>
  );
}
